const RPC = 'https://rpc.mainnet.chain.robinhood.com';
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const QUADS = '0x7b3AF27CEcd000c27Ce82eC85bD56f77181867FE';
async function rpc(method, params) {
  const res = await fetch(RPC, { method: 'POST', headers: { 'Content-Type': 'application/json', 'User-Agent': UA },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }) });
  const d = await res.json(); if (d.error) throw new Error(JSON.stringify(d.error).slice(0,100)); return d.result;
}
(async () => {
  const code = (await rpc('eth_getCode', [QUADS, 'latest'])).slice(2);
  const bytes = Buffer.from(code, 'hex');
  const sels = new Set();
  for (let i = 0; i < bytes.length - 5; i++) {
    if (bytes[i] === 0x63) sels.add('0x' + bytes.slice(i + 1, i + 5).toString('hex'));
  }
  const list = [...sels];
  console.log('total:', list.length);
  for (const s of list) {
    try {
      const r = await fetch(`https://www.4byte.directory/api/v1/signatures/?hex_signature=${s}`, { headers: { 'User-Agent': UA } });
      const j = await r.json();
      const sig = (j.results || []).map(x => x.text_signature).join(' | ') || 'UNKNOWN';
      if (/mint|claim|sale|drop|press|allow/i.test(sig)) console.log(s, '->', sig);
    } catch (e) {}
  }
  console.log('done');
})().catch(e => { console.error('FAILED:', e.message); process.exit(1); });
